const body = $json.body || {};
const content = body.content || body.message || body.data?.content || {};
const contact = body.contact || body.sender || {};

const doc = content.document || content.image || body.document || null;

const chatInput = String(content.text || content.body || content.caption || body.message || '').trim();
let phone = String(contact.number || contact.id?.user || body.phone || '').replace(/\D/g, '');
if (!phone) return [{ json: { ignore: true } }];
if (!phone.startsWith('55')) phone = '55' + phone;

const mediaBase64 =
  content.media ||
  content.base64 ||
  doc?.base64 ||
  doc?.data ||
  body.mediaBase64 ||
  body.document?.base64 ||
  null;

const mimetype = String(
  content.mimetype || content.mimeType || doc?.mimetype || doc?.mime_type || body.mimetype || ''
).toLowerCase();

const fileName =
  content.fileName ||
  content.filename ||
  doc?.fileName ||
  doc?.file_name ||
  body.fileName ||
  null;

if (!chatInput && !mediaBase64 && !fileName && !mimetype) return [{ json: { ignore: true } }];

return [{
  json: {
    ignore: false,
    phone,
    sessionId: phone,
    chatInput,
    mediaBase64,
    mimetype,
    fileName,
    rawPayload: body,
    history: []
  }
}];

const item = $input.first().json || {};
const p = item.mychatPayload || {};
const number = String(p.number || item.phone || '').replace(/\D/g, '');
const msg = String(p.body || item.message || '').replace(/[\r\n]+/g, ' ').trim();
if (!number || !msg) throw new Error('API nao retornou dados para MyChat');

return [{ json: {
  number,
  body: msg,
  externalKey: p.externalKey || `lead_${number}`,
  isClosed: p.isClosed === true
} }];
